import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/common/Navbar';
import Footer from './components/common/Footer';
import HeroSection from './components/home/HeroSection';
import FeaturesSection from './components/home/FeaturesSection';
import DestinationGrid from './components/home/DestinationGrid';
import TourPackages from './components/home/TourPackages';
import BookingSteps from './components/home/BookingSteps';
import Carousel3D from './components/Carousel3D';
import { getLatestMovies } from './api/tmdb';
import './App.css';

// 메인 랜딩 페이지 컴포넌트
function Home({ movies }) {
  return (
    <>
      <HeroSection />
      <Carousel3D movies={movies} />
      <DestinationGrid movies={movies} />
      <FeaturesSection />
      <TourPackages />
      <BookingSteps />
    </>
  );
}

function App() {
  const [movies, setMovies] = useState([]);

  useEffect(() => {
    const fetchMovies = async () => {
      const data = await getLatestMovies();
      if (data) setMovies(data);
    };
    fetchMovies();
  }, []);

  return (
    <Router>
      <div className="bg-[#0b090e] min-h-screen text-white font-sans flex flex-col justify-between">
        <Navbar />
        <main className="flex-grow">
          <Routes>
            <Route path="/" element={<Home movies={movies} />} />
            {/* 추후 상세 페이지 등 추가 라우트 설정 영역 */}
          </Routes>
        </main>
        <Footer />
      </div>
    </Router>
  );
}

export default App;
